  a: Inputs.range([-1, 1], {value: -0.70, step: 0.05, label: "Procjena za oblak A"}),
  b: Inputs.range([-1, 1], {value: -0.20, step: 0.05, label: "Procjena za oblak B"}),
  c: Inputs.range([-1, 1], {value: 0.20, step: 0.05, label: "Procjena za oblak C"}),
  d: Inputs.range([-1, 1], {value: 0.50, step: 0.05, label: "Procjena za oblak D"})
})









Prikaži kod
w06_scenariji = {
  const ciljevi = [
    {oblak: "Oblak A", rho: -0.80},
    {oblak: "Oblak B", rho: -0.35},
    {oblak: "Oblak C", rho: 0.40},
    {oblak: "Oblak D", rho: 0.75}
  ];

  function korelacija(podaci) {
    const mx = d3.mean(podaci, d =&gt; d.x);
    const my = d3.mean(podaci, d =&gt; d.y);
    const brojnik = d3.sum(podaci, d =&gt; (d.x - mx) * (d.y - my));
    const nazivnik = Math.sqrt(
      d3.sum(podaci, d =&gt; (d.x - mx) ** 2) *
      d3.sum(podaci, d =&gt; (d.y - my) ** 2)
    );
    return brojnik / nazivnik;
  }

  return ciljevi.map((scenarij, j) =&gt; {
    const rng = d3.randomLcg(606 + j);
    const normalna = d3.randomNormal.source(rng)(0, 1);
    const podaci = Array.from({length: 54}, () =&gt; {
      const x = normalna();
      const z = normalna();
      const y = scenarij.rho * x + Math.sqrt(1 - scenarij.rho ** 2) * z;
      return {oblak: scenarij.oblak, x, y};
    });
    return {...scenarij, r: korelacija(podaci), podaci};
  });
}









