    style: "percent",
    maximumFractionDigits: 0
  });

  function erf(x) {
    const predznak = x &lt; 0 ? -1 : 1;
    const z = Math.abs(x);
    const t = 1 / (1 + 0.3275911 * z);
    const y = 1 - (((((1.061405429 * t - 1.453152027) * t) +
      1.421413741) * t - 0.284496736) * t + 0.254829592) *
      t * Math.exp(-z * z);
    return predznak * y;
  }

  const normalnaF = x =&gt; 0.5 * (1 + erf(x / Math.SQRT2));

  function kvantilNormalne(p) {
    let donja = -8;
    let gornja = 8;
    for (let i = 0; i &lt; 60; i += 1) {
      const sredina = (donja + gornja) / 2;
      if (normalnaF(sredina) &lt; p) donja = sredina;
      else gornja = sredina;
    }
    return (donja + gornja) / 2;
  }

  const kriticna = kvantilNormalne(1 - w11_par.prag / 2);
  const rng = d3.randomLcg(1111);
