Prikaži kod
{
  if (!graf.nodes.length) {
    return htl.html`&lt;div class="empty-state" role="status"&gt;
      &lt;div class="empty-state-title"&gt;Pojmovnik se još gradi&lt;/div&gt;
      &lt;p&gt;Formalno definirani pojmovi pojavit će se ovdje kada njihovi zapisi
      budu spremni. Do tada nema praznih filtara ni neispunjene mreže.&lt;/p&gt;
    &lt;/div&gt;`;
  }

  const sirina = 900, visina = 560;
  const idovi = new Set(vidljivi.map(n =&gt; n.id));
  const cvorovi = vidljivi.map(n =&gt; ({...n}));
  const bridovi = graf.edges
    .filter(e =&gt; idovi.has(e.source) && idovi.has(e.target) && e.weight &gt;= 2)
    .map(e =&gt; ({...e}));

  const boja = "var(--tok-accent)";
  const crta = "var(--tok-ink-faint)";
  const tekst = "var(--tok-ink)";

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, sirina, visina])
    .attr("class", "concept-map");

  const sim = d3.forceSimulation(cvorovi)
    .force("link", d3.forceLink(bridovi).id(d =&gt; d.id).distance(70).strength(0.3))
    .force("charge", d3.forceManyBody().strength(-160))
    .force("center", d3.forceCenter(sirina / 2, visina / 2))
    .force("collide", d3.forceCollide(22));

  const link = svg.append("g")
    .attr("stroke", crta).attr("stroke-opacity", 0.45)
    .selectAll("line").data(bridovi).join("line")
    .attr("stroke-width", d =&gt; Math.min(3, 0.5 + d.weight / 4));

  const g = svg.append("g").selectAll("g").data(cvorovi).join("g")
    .style("cursor", "pointer");

  g.append("circle")
    .attr("r", d =&gt; 4 + Math.min(10, (d.mentions || 1) * 1.4))
    .attr("fill", boja).attr("fill-opacity", 0.75)
    .append("title").text(d =&gt; d.firstSentence || d.term);

  g.append("text")
    .attr("x", 10).attr("dy", "0.32em")
    .attr("fill", tekst)
    .text(d =&gt; d.term);

  sim.on("tick", () =&gt; {
    link.attr("x1", d =&gt; d.source.x).attr("y1", d =&gt; d.source.y)
        .attr("x2", d =&gt; d.target.x).attr("y2", d =&gt; d.target.y);
    g.attr("transform", d =&gt; `translate(${d.x},${d.y})`);
  });

  invalidation.then(() =&gt; sim.stop());
  return svg.node();
}









